/**
 * The authority budget of R7 decision D7 (docs/r7/00-ARCHITECTURE-DECISIONS.md D7; the rule and its corrections in
 * experiments/r7/S1-science/D7-authority-budget.md, sections 2 to 5): the TypeScript port in rail/authority.ts of the
 * reference implementation experiments/r7/S1-science/d7/budget.py. No chain here; the chain's side is in
 * authority-ledger.test.ts and the rail's in authority-rail.test.ts.
 *
 *   1. Cross-implementation fixtures: 400 random event sequences (4,558 events, 1,248 of them refused) with the
 *      reference's answer after every event, generated by d7/fixtures_d7.py (seed 20261120) with the quant
 *      environment into test/fixtures/d7_fixtures.json. The port must give the same answer to every event.
 *   2. The spec's counterexamples, at the rule's level: round trips, self-payments, self-dealt escrow and a second
 *      workspace of the same person do not raise the budget; F1b (a second workspace NOT in the principal set) does,
 *      which is why the principal set must list it; F5 (rounding to nearest) leaks and safe rounding does not.
 *   3. A seeded property test over random sequences with the adversarial structures of section 5 (payments to the agent
 *      key, colluding clients, the owner's addresses and other workspaces as clients, holds settled to self, refunds,
 *      reversals, round trips with the truth anywhere in the band, amounts small enough for rounding to matter): the
 *      budget never rises except by a credit, a reversal or a grant; credits only for outside clients, once, after k
 *      confirmations; a refused event changes nothing; the log replays to the same figures; availability never goes
 *      below zero without a reorganisation; no stretch of circular events raises the budget. And it has teeth: the same
 *      generator and oracle catch a rule that does not floor conversion costs and a rule that credits a client in P.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { CHAIN } from "./helpers.ts";
import { AuthorityBudget, CIRCULAR_KINDS, NUMERAIRE, RAISING_KINDS, Refused, band, parseQ, q, replay, type Band, type Entry, type Params } from "../rail/authority.ts";

const FIXTURES = join(CHAIN, "test", "fixtures", "d7_fixtures.json");
const bandOf = (b: [string, string, string]): Band => band(parseQ(b[0]), parseQ(b[1]), parseQ(b[2]));
const big = (x: number | null) => (x === null ? null : BigInt(x));

/** One fixture event applied to the port; returns what the reference's method returned. */
function apply(b: AuthorityBudget, ev: any): bigint {
  switch (ev.kind) {
    case "pay": return b.pay(ev.id, ev.to, BigInt(ev.qty), bandOf(ev.band));
    case "convert": return b.convert(ev.id, BigInt(ev.qty_in), bandOf(ev.band_in), BigInt(ev.qty_out), bandOf(ev.band_out), ev.recipient);
    case "hold": return b.hold(ev.id, BigInt(ev.amount), ev.counterparty);
    case "settle": return b.settleHold(ev.id, ev.payee);
    case "release": return b.releaseHold(ev.id);
    case "credit": return b.credit(ev.id, ev.client, ev.payee, BigInt(ev.qty), bandOf(ev.band), ev.confirmations);
    case "uncredit": return b.uncredit(ev.id);
    case "reversal": return b.reversal(ev.id, BigInt(ev.qty), bandOf(ev.band));
    case "fee": return b.fee(ev.id, parseQ(ev.value));
    case "grant": return b.grant(ev.id, BigInt(ev.amount));
    default: throw new Error(`unknown fixture event ${ev.kind}`);
  }
}

test("cross-implementation fixtures: the port answers all 400 sequences of the Python reference exactly, event by event", () => {
  const raw = readFileSync(FIXTURES);
  // the file the experiment recorded on 20 Nov 2026 (results/d7_fixtures.json); regenerated with the quant environment on 22 Nov, byte-identical
  assert.equal(createHash("sha256").update(raw).digest("hex"), "6826af55302425f7eefc02c66bccd9c2d5db0f6f91639ab64ef6e061df2dfce1");
  const fx = JSON.parse(raw.toString("utf8")) as { seed: number; cases: any[] };
  assert.equal(fx.seed, 20261120);
  let events = 0, refused = 0;
  const kinds = new Set<string>(), meters = new Set<string>(), roundings = new Set<string>();
  for (const [i, c] of fx.cases.entries()) {
    const params: Params = { base: BigInt(c.params.base), rate: parseQ(c.params.rate), confirmations: c.params.confirmations, meter: c.params.meter, rounding: c.params.rounding };
    meters.add(c.params.meter); roundings.add(c.params.rounding);
    const b = new AuthorityBudget(params, c.control, c.principal);
    for (const [j, ev] of c.events.entries()) {
      let got: { ok: boolean; returned: bigint | null; budget: bigint; available: bigint };
      try {
        const r = apply(b, ev);
        got = { ok: true, returned: r, budget: b.budget, available: b.available };
      } catch (e) {
        if (!(e instanceof Refused)) throw new Error(`case ${i} event ${j} (${ev.kind}): ${(e as Error).message}`);
        got = { ok: false, returned: null, budget: b.budget, available: b.available };
      }
      const want = { ok: ev.expect.ok, returned: big(ev.expect.returned), budget: BigInt(ev.expect.budget), available: BigInt(ev.expect.available) };
      assert.deepEqual(got, want, `case ${i} event ${j} (${ev.kind} ${ev.id}, ${c.params.meter}, ${c.params.rounding})`);
      events++; if (!want.ok) refused++;
      kinds.add(ev.kind);
    }
    assert.deepEqual(replay(params, b.log), { budget: b.budget, available: b.available }, `case ${i}: the log replays to the same figures`);
  }
  assert.deepEqual([fx.cases.length, events, refused], [400, 4558, 1248]);
  assert.deepEqual([...kinds].sort(), ["convert", "credit", "fee", "grant", "hold", "pay", "release", "reversal", "settle", "uncredit"]);
  assert.deepEqual([[...meters].sort(), [...roundings].sort()], [["conservative", "mid"], ["nearest", "safe"]]);
});

// ───────────── the counterexamples of section 4, at the rule's level ─────────────
const T = 1_000_000n; // tUSD base units, as in the spec's figures
const C = ["vault", "owner"], P = [...C, "agent", "alt", "ws2"];
const fresh = (o: Partial<Params> = {}, principal = P) => new AuthorityBudget({ base: 10n * T, rate: q(1n, 2n), confirmations: 2, ...o }, C, principal);
const zBand = (mid: bigint, hwBps: bigint) => band(q(mid * (10_000n - hwBps), 10_000n), q(mid), q(mid * (10_000n + hwBps), 10_000n));

test("round trips at the reference mid, with the truth anywhere in the band, never raise the budget (F4's trades); the conservative meter meters them, the mid meter does not", () => {
  for (const meter of ["conservative", "mid"] as const) {
    const b = fresh({ meter });
    const z = zBand(2n, 500n); // 2 ± 5%, the spec's F4
    let before = b.budget, refused = 0;
    const leg = (f: () => bigint) => { try { f(); } catch (e) { if (!(e instanceof Refused)) throw e; refused++; } };
    for (let i = 0; i < 30; i++) {
      leg(() => b.convert(`buy${i}`, 20n * T, NUMERAIRE, 10n * T, z, "vault")); // 20 tUSD for 10 Z at the mid
      assert.ok(b.budget <= before, `${meter}: buying never raises it`); before = b.budget;
      leg(() => b.convert(`sell${i}`, 10n * T, z, 20n * T, NUMERAIRE, "vault"));
      assert.ok(b.budget <= before, `${meter}: selling never raises it`); before = b.budget;
    }
    if (meter === "mid") assert.deepEqual([b.budget, refused], [10n * T, 0], "the mid meter sees nothing (the leak of F4)");
    else {
      // each leg costs 1 tUSD at the band's edges (20 − 10·1.9; 10·2.1 − 20): the 10 tUSD base lasts five round trips, then every leg is refused
      assert.deepEqual([b.budget, b.available, refused], [0n, 0n, 50], "the conservative meter charges what is given at the top of the band less what is received at the bottom");
    }
  }
});

test("self-payments, holds settled to self and refunds leave the budget where it was; availability comes back", () => {
  const b = fresh();
  assert.equal(b.pay("p1", "vault", 5n * T), 0n);
  assert.equal(b.pay("p2", "owner", 7n * T), 0n);
  assert.equal(b.hold("h1", 4n * T, "escrow"), -4n * T);
  assert.equal(b.available, 6n * T);
  assert.equal(b.settleHold("h1", "vault"), 4n * T, "a hold settled to the workspace (self-dealt escrow) gives availability back");
  b.hold("h2", 3n * T, "vendor");
  assert.equal(b.releaseHold("h2"), 3n * T, "a refund gives it back");
  assert.deepEqual([b.budget, b.available], [10n * T, 10n * T]);
  assert.ok(b.log.every((e) => e.deltaBudget === 0n));
});

test("self-dealt escrow does not raise the budget: the owner, the agent key, the person's other address and a linked second workspace are clients in P", () => {
  const b = fresh();
  for (const [i, client] of ["owner", "vault", "agent", "alt", "ws2"].entries()) assert.equal(b.credit(`j${i}`, client, "vault", 100n * T, NUMERAIRE, 5), 0n, client);
  assert.equal(b.budget, 10n * T);
  // and 10 cycles of the spec's F1b through a LINKED second workspace: nothing
  for (let i = 0; i < 10; i++) b.credit(`ws2-${i}`, "ws2", "vault", 100n * T, NUMERAIRE, 5);
  assert.equal(b.budget, 10n * T);
  // the same cycles through a second workspace that is NOT in P are credited: F1b, the reason P must list it (A-ID)
  const unlinked = fresh({}, P.filter((x) => x !== "ws2"));
  for (let i = 0; i < 10; i++) unlinked.credit(`ws2-${i}`, "ws2", "vault", 100n * T, NUMERAIRE, 5);
  assert.equal(unlinked.budget, 510n * T, "F1b: 510 tUSD of authority with no earnings, the figure of results/d7_counterexamples.json");
  // credits need a payee in C, k confirmations, and count once per job
  assert.equal(b.credit("x1", "client", "vendor", 100n * T, NUMERAIRE, 5), 0n);
  assert.equal(b.credit("x2", "client", "vault", 100n * T, NUMERAIRE, 1), 0n);
  assert.equal(b.credit("x2", "client", "vault", 101n, NUMERAIRE, 2), 50n);
  assert.equal(b.credit("x2", "client", "vault", 101n, NUMERAIRE, 2), 0n);
});

test("R2 under the revised rule: a fair conversion of 10 tUSD costs nothing measurable at an exact reference, and a 1 tUSD payment then passes", () => {
  const b = fresh();
  assert.equal(b.convert("c", 10n * T, NUMERAIRE, 5n * T, band(q(2n), q(2n), q(2n)), "vault"), 0n);
  assert.equal(b.pay("p", "vendor", 1n * T), -1n * T);
  assert.equal(b.budget, 9n * T);
});

test("F5: rounding to nearest admits 3,000 sub-unit sales with nothing metered; outward rounding admits none", () => {
  const z = band(q(245n, 100n), q(5n, 2n), q(255n, 100n));
  const run = (rounding: "safe" | "nearest") => {
    const b = fresh({ base: 0n, rounding });
    let n = 0;
    for (let i = 0; i < 3000; i++) { try { b.convert(`s${i}`, 4n, z, 10n, NUMERAIRE, "vault"); n++; } catch (e) { if (!(e instanceof Refused)) throw e; } }
    return { n, budget: b.budget };
  };
  assert.deepEqual(run("nearest"), { n: 3000, budget: 0n });
  assert.deepEqual(run("safe"), { n: 0, budget: 0n });
});

test("the rule refuses what would make availability negative and changes nothing; facts mode applies what already happened", () => {
  const b = fresh({ base: 10n });
  assert.throws(() => b.pay("p", "vendor", 11n), Refused);
  assert.throws(() => b.hold("h", 11n, "vendor"), Refused);
  assert.deepEqual([b.budget, b.available, b.log.length], [10n, 10n, 0]);
  const f = new AuthorityBudget({ base: 10n, rate: q(1n, 2n), confirmations: 2 }, C, P, { facts: true });
  assert.equal(f.pay("p", "vendor", 11n), -11n);
  assert.deepEqual([f.budget, f.available], [-1n, -1n]);
  assert.throws(() => new AuthorityBudget({ base: 0n, rate: q(1n), confirmations: 0 }, ["vault"], ["owner"]), /control/);
  assert.throws(() => band(q(2n), q(1n), q(3n)), /lo/);
  assert.throws(() => new AuthorityBudget({ base: -1n, rate: q(1n), confirmations: 0 }, C, P), /non-negative/);
});

// ───────────── the property test (section 5's oracle, O1 O2 O3 O5) ─────────────
/** mulberry32: the same sequences on every run. */
const rng = (seed: number) => () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const ADDRS = ["vault", "owner", "agent", "alt", "ws2", "vendor", "client", "colluder", "venue", "escrow"];
const OUTSIDE = new Set(["vendor", "client", "colluder", "venue", "escrow"]);

interface Violation { seed: number; step: number; what: string }

/** Runs `sequences` random sequences against rules made by `make`; returns the first oracle violation, or null. */
function explore(make: (p: Params) => AuthorityBudget, sequences: number, steps: number, seed0: number): { violation: Violation | null; events: number; refused: number; raised: Record<string, number> } {
  let events = 0, refused = 0;
  const raised: Record<string, number> = {};
  for (let s = 0; s < sequences; s++) {
    const r = rng(seed0 + s);
    const int = (lo: number, hi: number) => lo + Math.floor(r() * (hi - lo + 1));
    const pick = <X,>(xs: readonly X[]) => xs[Math.floor(r() * xs.length)];
    // amounts from one base unit to 50 tUSD, often tiny so that rounding matters
    const amt = () => BigInt(r() < 0.3 ? int(0, 9) : int(1, 50_000_000));
    const params: Params = { base: BigInt(int(0, 30_000_000)), rate: pick([q(0n), q(1n, 4n), q(1n, 2n), q(1n)]), confirmations: int(0, 3) };
    const b = make(params);
    let mid = q(BigInt(int(1, 400)), BigInt(int(1, 100)));
    let z = zBand(1n, 0n);
    const tick = () => { mid = q(mid.n * BigInt(int(80, 120)), mid.d * 100n); if (mid.n === 0n) mid = q(1n, 100n); const hw = BigInt(int(0, 1000)); z = band(q(mid.n * (10_000n - hw), mid.d * 10_000n), mid, q(mid.n * (10_000n + hw), mid.d * 10_000n)); };
    tick();
    let reorganised = false, circularStart: bigint | null = null;
    const credited = new Set<string>();
    for (let i = 0; i < steps; i++) {
      const before = { budget: b.budget, available: b.available, n: b.log.length };
      const kind = pick(["pay", "pay-agent", "convert", "round-trip", "hold", "settle", "release", "credit", "credit-self", "uncredit", "reversal", "fee", "grant", "tick"] as const);
      let circular = false;
      try {
        switch (kind) {
          case "tick": tick(); circular = true; break;
          case "pay": { const to = pick(ADDRS); b.pay(`p${i}`, to, amt(), r() < 0.5 ? NUMERAIRE : z); circular = C.includes(to); break; } // to C: a self-payment
          case "pay-agent": b.pay(`pa${i}`, "agent", amt()); break; // F6's structure: the agent key is outside C
          case "convert": { const toC = r() < 0.8; b.convert(`c${i}`, amt(), r() < 0.5 ? NUMERAIRE : z, amt(), r() < 0.5 ? NUMERAIRE : z, toC ? pick(C) : pick([...OUTSIDE, "agent"])); circular = toC; break; }
          case "round-trip": {
            // buy at the reference mid, sell at mid: with the truth anywhere inside the band (F4's structure)
            const usd = amt() + 1n, zq = (usd * mid.d) / mid.n;
            b.convert(`rb${i}`, usd, NUMERAIRE, zq, z, "vault");
            tick();
            b.convert(`rs${i}`, zq, z, (zq * mid.n) / mid.d, NUMERAIRE, "vault");
            circular = true; break;
          }
          case "hold": b.hold(`h${i}`, amt(), pick(["vendor", "colluder", "escrow"])); circular = true; break;
          case "settle": { const ids = [...b.holds.keys()]; if (ids.length) { const to = pick(ADDRS); b.settleHold(pick(ids), to); circular = C.includes(to); } else circular = true; break; }
          case "release": { const ids = [...b.holds.keys()]; if (ids.length) b.releaseHold(pick(ids)); circular = true; break; }
          case "credit": { const id = r() < 0.2 && credited.size ? pick([...credited]) : `j${i}`; const client = pick(ADDRS); b.credit(id, client, pick([...C, ...C, "vendor"]), amt(), r() < 0.7 ? NUMERAIRE : z, int(0, 4)); credited.add(id); circular = P.includes(client); break; }
          case "credit-self": b.credit(`js${i}`, pick(P), pick(C), amt(), NUMERAIRE, int(2, 5)); circular = true; break; // self-dealt escrow
          case "uncredit": { const ids = [...b.credited.keys()]; if (ids.length) { b.uncredit(pick(ids)); reorganised = true; } break; }
          case "reversal": { const ids = [...b.restorable.keys()]; b.reversal(ids.length && r() < 0.8 ? pick(ids) : "none", amt(), r() < 0.5 ? NUMERAIRE : z); break; }
          case "fee": b.fee(`f${i}`, q(amt(), BigInt(int(1, 7)))); break;
          case "grant": b.grant(`g${i}`, amt()); break;
        }
      } catch (e) {
        if (!(e instanceof Refused)) throw e;
        refused++;
        // O1: a refused event appends nothing and changes nothing (a round trip's first leg may have been admitted)
        if (kind !== "round-trip" && (b.log.length !== before.n || b.budget !== before.budget || b.available !== before.available)) return { violation: { seed: seed0 + s, step: i, what: `refused ${kind} changed something` }, events, refused, raised };
      }
      events++;
      // O2: every rise is a credit (payee in C, client outside P, once per job, after k confirmations), a reversal or a grant
      for (const e of b.log.slice(before.n) as Entry[]) {
        if (e.deltaBudget > 0n) {
          raised[e.kind] = (raised[e.kind] ?? 0) + 1;
          if (!RAISING_KINDS.has(e.kind)) return { violation: { seed: seed0 + s, step: i, what: `${e.kind} raised the budget by ${e.deltaBudget}` }, events, refused, raised };
        }
        if (e.kind === "credit" && kind === "credit-self") return { violation: { seed: seed0 + s, step: i, what: "a client in P was credited" }, events, refused, raised };
      }
      // O1: the log alone replays to the figures
      const rep = replay(params, b.log);
      if (rep.budget !== b.budget || rep.available !== b.available) return { violation: { seed: seed0 + s, step: i, what: "the log does not replay" }, events, refused, raised };
      // O3: availability stays at or above zero while no credit was removed (A-FIN)
      if (!reorganised && b.available < 0n) return { violation: { seed: seed0 + s, step: i, what: `available ${b.available} below zero` }, events, refused, raised };
      // O5 (theorem T2): over a stretch of circular events only (conversions with output to C, payments to C, holds,
      // releases, holds settled to C, receipts from clients in P), the budget at the end is at most what it was at the start
      if (circular) {
        if (circularStart === null) circularStart = before.budget;
        if (b.budget > circularStart) return { violation: { seed: seed0 + s, step: i, what: `a circular stretch raised the budget from ${circularStart} to ${b.budget} (${kind})` }, events, refused, raised };
        if (!b.log.slice(before.n).every((e) => CIRCULAR_KINDS.has(e.kind))) return { violation: { seed: seed0 + s, step: i, what: `a circular ${kind} was recorded as ${b.log.slice(before.n).map((e) => e.kind).join(", ")}` }, events, refused, raised };
      } else circularStart = null;
    }
  }
  return { violation: null, events, refused, raised };
}

test("property: over 3,000 seeded sequences of up to 60 events the budget rises only by credits, reversals and grants, and every other oracle holds", (t) => {
  const out = explore((p) => new AuthorityBudget(p, C, P), 3000, 60, 20261122);
  t.diagnostic(`3000 sequences, ${out.events} events, ${out.refused} refused; rises by kind ${JSON.stringify(out.raised)}`);
  assert.equal(out.violation, null, JSON.stringify(out.violation));
  assert.ok(out.events > 150_000 && out.refused > 1_000, `events ${out.events}, refused ${out.refused}`);
  for (const k of ["credit", "reversal", "grant"]) assert.ok((out.raised[k] ?? 0) > 100, `${k} raised the budget in some sequences: ${JSON.stringify(out.raised)}`);
});

test("the property test has teeth: a rule that does not floor conversion costs, and one that credits a client in P, are caught", (t) => {
  class Unfloored extends AuthorityBudget {
    override convert(opId: string, qtyIn: bigint, bandIn: Band, qtyOut: bigint, bandOut: Band, recipient: string): bigint {
      if (!this.control.has(recipient)) return super.convert(opId, qtyIn, bandIn, qtyOut, bandOut, recipient);
      const gain = qtyOut * bandOut.lo.n * bandIn.hi.d - qtyIn * bandIn.hi.n * bandOut.lo.d;
      if (gain <= 0n) return super.convert(opId, qtyIn, bandIn, qtyOut, bandOut, recipient);
      const g = gain / (bandIn.hi.d * bandOut.lo.d);
      this.budget += g;
      this.log.push({ kind: "convert", opId, deltaBudget: g, deltaAvailable: g });
      return g;
    }
  }
  class SelfCredit extends AuthorityBudget {
    override credit(jobId: string, client: string, payee: string, qty: bigint, b: Band, confirmations: number): bigint {
      return super.credit(jobId, this.principal.has(client) ? "client" : client, payee, qty, b, confirmations);
    }
  }
  const a = explore((p) => new Unfloored(p, C, P), 400, 60, 7);
  t.diagnostic(`unfloored conversions: ${JSON.stringify(a.violation)}`);
  assert.ok(a.violation && /convert raised the budget|circular stretch raised/.test(a.violation.what), JSON.stringify(a.violation));
  const s = explore((p) => new SelfCredit(p, C, P), 400, 60, 7);
  t.diagnostic(`credits for clients in P: ${JSON.stringify(s.violation)}`);
  assert.ok(s.violation && /client in P was credited|circular stretch raised|was recorded as credit/.test(s.violation.what), JSON.stringify(s.violation));
});
